"""Read-only XLSX snapshot browser regression; fixture generated by viewer.test.mjs."""
import argparse, os, subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright
parser=argparse.ArgumentParser();parser.add_argument('--url',required=True);args=parser.parse_args()
root=Path(__file__).resolve().parents[2]
fixture=root/'web/test-results/viewer.xlsx';fixture.parent.mkdir(exist_ok=True)
subprocess.run(['node','--input-type=module','-e',"import {viewerFixture} from './tests/viewer.test.mjs';import fs from 'node:fs';fs.writeFileSync('test-results/viewer.xlsx',await viewerFixture())"],cwd=root/'web',check=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH'),args=['--no-sandbox'])
 page=browser.new_page(viewport={'width':1440,'height':1000});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto(args.url+'#calc-viewer');page.locator('#xlsx-viewer').wait_for(state='visible')
 page.locator('#xlsx-viewer input[type=file]').set_input_files(str(fixture))
 page.locator('#viewer-table').get_by_text('=UNSUPPORTED(1)',exact=True).wait_for()
 assert page.locator('#viewer-table tr').filter(has_text='Нет сохранённого результата').count()==1
 assert page.locator('#viewer-table').get_by_text('0',exact=True).count()==1
 assert page.locator('#viewer-table').get_by_text('false',exact=True).count()==1
 assert page.locator('#viewer-table').get_by_text('<script>alert(1)</script>',exact=True).count()==1
 page.screenshot(path=str(root/'web/test-results/xlsx-viewer.png'),full_page=True)
 page.locator('#viewer-sheet').select_option(label='Пустой');assert page.locator('#viewer-table tbody tr').count()==0
 page.locator('#navigation button[data-id="0"]').click();page.locator('#calculator').wait_for(state='visible')
 page.locator('#navigation button[data-id="viewer"]').click();page.locator('#viewer-sheet').select_option(label='Данные')
 for width in [900,640,390]:
  page.set_viewport_size({'width':width,'height':900})
  assert page.evaluate('document.documentElement.scrollWidth <= window.innerWidth+1')
 assert not errors,errors
 browser.close()
print('Viewer browser: cached values, formula text, missing result, empty sheet, navigation, responsive widths passed')
